package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.json.JsonMapper;
import com.ruoyi.medical.contracts.*;
import java.nio.charset.StandardCharsets;
import java.util.*;

/** Dedicated N04 compiler. Only physically read immutable registered packages and the
 * original registered SECTION_WRITER input may contribute bytes. No TASK plan is synthesized. */
public final class TaskSectionWriterPromptCompiler {
 public static final String URI="urn:medical:task-section-writer-package:1.0.0";
 public static final String PROMPT_REF=URI+"#/$defs/PromptPackage", ROLE_REF=URI+"#/$defs/RolePackage", PROFILE_REF=URI+"#/$defs/ProfilePackage";
 private final FormalCapabilityIdentityAuthority capabilities;private final PermissionSchema json;private final String packageSchemaSha256;
 private final JsonMapper parser=JsonMapper.builder().enable(com.fasterxml.jackson.core.StreamReadFeature.STRICT_DUPLICATE_DETECTION).enable(com.fasterxml.jackson.databind.DeserializationFeature.FAIL_ON_TRAILING_TOKENS).build();
 public TaskSectionWriterPromptCompiler(FormalCapabilityIdentityAuthority capabilities,PermissionSchema json)throws Exception {this.capabilities=capabilities;this.json=json;try(var in=Objects.requireNonNull(getClass().getResourceAsStream("/task-section-writer-package.schema.json"))){packageSchemaSha256=WireValues.sha256(in.readAllBytes());}}
 public PermissionProtocol.Basis roleArtifact(TaskSectionWriterRuntimeAuthority.Verified a)throws Exception {a.requireUnchanged();var j=a.job();return capabilities.requireRegisteredIdentity(j.tenant(),j.actor(),basis(admitted(a).required("role_version")),"ROLE",j.project()).sourceArtifact();}
 public PermissionProtocol.Basis profileArtifact(TaskSectionWriterRuntimeAuthority.Verified a)throws Exception {a.requireUnchanged();var p=runtime(a).required("profile").required("artifact");return new PermissionProtocol.Basis(text(p,"artifact_id"),text(p,"sha256"));}
 public PermissionProtocol.Basis promptArtifact(TaskSectionWriterRuntimeAuthority.Verified a,TaskInvocationPackages.Read role)throws Exception {a.requireUnchanged();role.requireCurrent(a.admission());requirePackage(roleArtifact(a),role);var r=read(role,a);var contract=a.input().evidenceContract();requirePublication(role,contract,"RolePackage");validateRole(r,contract.version());var b=basis(r.required("prompt_basis"));requirePublished(a,b);var j=a.job();return capabilities.requireRegisteredIdentity(j.tenant(),j.actor(),b,"PROMPT",j.project()).sourceArtifact();}
 private void requirePublished(TaskSectionWriterRuntimeAuthority.Verified a,PermissionProtocol.Basis b)throws Exception {boolean found=false;for(var pin:json.tree(a.input().production().replay().content().required("agent_release")).required("prompt_revisions"))if(sameTree(pin,json.tree(b)))found=true;if(!found)deny();}
 private JsonNode admitted(TaskSectionWriterRuntimeAuthority.Verified a)throws Exception{return a.input().manifest();}
 private JsonNode runtime(TaskSectionWriterRuntimeAuthority.Verified a)throws Exception{return a.input().production().replay().content().required("agent_release").required("runtime_manifest");}
 public Compiled compile(TaskSectionWriterRuntimeAuthority.Verified a,TaskSectionWriterHostAccess.InputContent input,TaskInvocationPackages.Read role,TaskInvocationPackages.Read prompt,TaskInvocationPackages.Read profile,TaskSectionWriterDeployment deployment,TaskSectionWriterContextReads.Reads reads)throws Exception {
  a.requireUnchanged();reads.requireFor(a);if(!a.inputSha256().equals(WireValues.sha256(input.bytes(a))))bad();
  var contract=a.input().evidenceContract();requirePublication(role,contract,"RolePackage");requirePublication(prompt,contract,"PromptPackage");requirePublication(profile,contract,"ProfilePackage");
  var r=read(role,a);var p=read(prompt,a);var f=read(profile,a);validateRole(r,contract.version());validatePrompt(p,contract.version());validateProfile(f,contract.version());
  requirePackage(roleArtifact(a),role);requirePackage(promptArtifact(a,role),prompt);requirePackage(profileArtifact(a),profile);
  var runtime=runtime(a);if(!sameTree(runtime.required("profile").required("artifact"),r.required("profile_artifact")))bad();requireDeployment(r,f,deployment.value(),runtime,contract.version());
  var document=compileDocument(p,parser.readTree(input.bytes(a)),contract.version());((com.fasterxml.jackson.databind.node.ObjectNode)document).set("writer_content",reads.content());byte[] bytes=ContentReadAuthorization.canonicalBytes(document);if(bytes.length>deployment.maximumBytes())throw new TenantAccessException(ErrorCode.CONTEXT_LIMIT);
  var pins=json.object().put("schema_version","1.0.0").put("compiler","N04_LITERAL_INSTRUCTIONS_AND_REGISTERED_INPUT_V1").put("input_artifact_id",a.input().inputId()).put("input_sha256",a.inputSha256()).put("input_receipt_sha256",a.input().receiptSha256()).put("launch_sha256",WireValues.sha256(bytes));
  pins.set("writer_content",reads.canonicalPins());pins.set("role_basis",admitted(a).required("role_version"));pins.set("prompt_basis",r.required("prompt_basis"));pins.set("role_package",role.canonicalPins());pins.set("prompt_package",prompt.canonicalPins());pins.set("profile_package",profile.canonicalPins());pins.set("adapter_artifact",f.required("adapter_artifact"));
  return new Compiled(a,input,role,prompt,profile,deployment,pins,bytes,List.of(text(f,"system_prefix")),reads);
 }
 private static void requirePublication(TaskInvocationPackages.Read read,TaskWriterEvidenceContract contract,String definition)throws Exception {var c=SchemaCatalogue.fromClasspath();if(!c.schemaRef(contract.packages(),definition).equals(read.schemaRef())||!c.schemaDigest(contract.packages()).equals(read.schemaSha256()))bad();c.bindPublished(read.schemaRef(),read.schemaSha256(),read.bytes());}
 static JsonNode compileDocument(JsonNode prompt,JsonNode input,String version){validatePrompt(prompt,version);var legacy=legacy(prompt,version);var result=(com.fasterxml.jackson.databind.node.ObjectNode)compileDocument(legacy,input);result.put("schema_version",version);return result;}
 static void validatePrompt(JsonNode n,String version){validatePrompt(legacy(n,version));}
 static void validateRole(JsonNode n,String version){validateRole(legacy(n,version));}
 static void validateProfile(JsonNode n,String version){validateProfile(legacy(n,version));}
 static void requireDeployment(JsonNode role,JsonNode profile,JsonNode deployment,JsonNode runtime,String version){requireDeployment(legacy(role,version),legacy(profile,version),deployment,runtime);}
 private static JsonNode legacy(JsonNode n,String version){if(!Set.of("1.0.0","2.0.0").contains(version)||!version.equals(text(n,"schema_version")))bad();var copy=(com.fasterxml.jackson.databind.node.ObjectNode)n.deepCopy();copy.put("schema_version","1.0.0");return copy;}
 private JsonNode read(TaskInvocationPackages.Read read,TaskSectionWriterRuntimeAuthority.Verified a)throws Exception {read.requireCurrent(a.admission());return parser.readTree(read.bytes());}
 private static void requirePackage(PermissionProtocol.Basis basis,TaskInvocationPackages.Read read){if(!basis.equals(read.artifact()))bad();}
 public final class Compiled {
  private final TaskSectionWriterContextReads.Reads reads;private final TaskSectionWriterRuntimeAuthority.Verified authority;private final TaskSectionWriterRuntimeAuthority.Job job;private final TaskSectionWriterHostAccess.InputContent input;private final TaskInvocationPackages.Read role,prompt,profile;private final TaskSectionWriterDeployment deployment;private final JsonNode pins;private final byte[] bytes;private final List<String> systems;
  private Compiled(TaskSectionWriterRuntimeAuthority.Verified authority,TaskSectionWriterHostAccess.InputContent input,TaskInvocationPackages.Read role,TaskInvocationPackages.Read prompt,TaskInvocationPackages.Read profile,TaskSectionWriterDeployment deployment,JsonNode pins,byte[] bytes,List<String> systems,TaskSectionWriterContextReads.Reads reads){this.reads=reads;this.authority=authority;this.job=authority.job();this.input=input;this.role=role;this.prompt=prompt;this.profile=profile;this.deployment=deployment;this.pins=pins.deepCopy();this.bytes=bytes.clone();this.systems=List.copyOf(systems);}
  public void requireFor(TaskSectionWriterRuntimeAuthority.Verified a)throws Exception {a.requireUnchanged();if(!job.equals(a.job()))deny();var fresh=compile(a,input,role,prompt,profile,deployment,reads);if(!sameTree(pins,fresh.pins)||!Arrays.equals(bytes,fresh.bytes))bad();}
  public JsonNode requireModelSend(EnterpriseAccess.Admission modelAdmission,TaskSectionWriterRuntimeAuthority.Verified a,String purpose,String provider)throws Exception {requireFor(a);var n=json.object();n.set("prompt",prompt.requireModelSend(modelAdmission,purpose,provider,a.input()));n.set("profile",profile.requireModelSend(modelAdmission,purpose,provider,a.input()));requireFor(a);return n;}
  public List<ArtifactRegistryProtocol.MemberRow> contentMembers(){var result=new TreeMap<String,ArtifactRegistryProtocol.MemberRow>();for(var read:List.of(role,prompt,profile))for(var member:read.contentMembers()){var old=result.putIfAbsent(member.upstreamVersionId(),member);if(old!=null&&!old.equals(member))bad();}return List.copyOf(result.values());}
  public List<String> contentRoots(){return contentMembers().stream().map(ArtifactRegistryProtocol.MemberRow::upstreamVersionId).sorted().toList();}
  public String launchText(){return new String(bytes,StandardCharsets.UTF_8);}public String payloadSha256(){return text(pins,"launch_sha256");}public JsonNode canonicalPins(){return pins.deepCopy();}public List<String> approvedSystemMessages(){return systems;}public PermissionProtocol.Basis promptBasis(){return basis(pins.required("prompt_basis"));}
  TaskSectionWriterInputAuthority.Verified input(){return authority.input();}
 }
 static JsonNode compileDocument(JsonNode prompt,JsonNode input){validatePrompt(prompt);if(!input.isObject()||!"N04".equals(text(input,"node_kind")))bad();var out=new JsonMapper().createObjectNode().put("schema_version","1.0.0").put("node_kind","N04").put("instructions",text(prompt,"system_instructions"));out.set("section_writer_input",input.deepCopy());return out;}
 static void validatePrompt(JsonNode n){ProfessionalRuntimeObservations.closed(n,Set.of("schema_version","node_kind","system_instructions","input_encoding"));version(n);if(!"SECTION_WRITER_INPUT_CANONICAL_JSON".equals(text(n,"input_encoding"))||text(n,"system_instructions").isBlank()||text(n,"system_instructions").getBytes(StandardCharsets.UTF_8).length>262144)bad();}
 static void validateRole(JsonNode n){ProfessionalRuntimeObservations.closed(n,Set.of("schema_version","node_kind","role_name","prompt_basis","profile_artifact"));version(n);if(!Set.of("SectionWriter").contains(text(n,"role_name")))bad();ProfessionalRuntimeObservations.closed(n.required("prompt_basis"),Set.of("version_id","content_sha256"));basis(n.required("prompt_basis"));artifact(n.required("profile_artifact"));}
 static void validateProfile(JsonNode n){ProfessionalRuntimeObservations.closed(n,Set.of("schema_version","node_kind","profile_name","projection","model_tool_mode","system_prefix","files","adapter_artifact"));version(n);if(!"SECTION_WRITER_N04_V1".equals(text(n,"model_tool_mode"))||!"medical-agent".equals(text(n,"profile_name"))||!"TEXT_SYSTEM_USER_V1".equals(text(n,"projection"))||text(n,"system_prefix").getBytes(StandardCharsets.UTF_8).length>262144)bad();artifact(n.required("adapter_artifact"));var files=n.required("files");if(!files.isArray()||files.isEmpty()||files.size()>256)bad();var paths=new HashSet<String>();for(var f:files){ProfessionalRuntimeObservations.closed(f,Set.of("relative","sha256","size_bytes"));String p=TaskProfessionalProfilePath.require(text(f,"relative"));if(!paths.add(p))bad();WireValues.hash(text(f,"sha256"));size(f);} }
 static void requireDeployment(JsonNode role,JsonNode profile,JsonNode deployment,JsonNode runtime){
  validateRole(role);validateProfile(profile);if(!text(profile,"model_tool_mode").equals(text(deployment,"model_tool_mode")))bad();if(!text(role,"role_name").equals(text(deployment,"role_name"))||!sameTree(role.required("profile_artifact"),deployment.required("profile_artifact")))bad();
  var expected=new TreeMap<String,String>();for(var f:profile.required("files"))expected.put(text(f,"relative"),text(f,"sha256"));var actual=new TreeMap<String,String>();for(var f:deployment.required("profile_files")){if(actual.put(text(f,"relative"),text(f,"sha256"))!=null)bad();}if(!actual.equals(expected))bad();
  boolean adapter=false;for(var p:runtime.required("event_adapters"))if("C07".equals(text(p,"component"))&&sameTree(p.required("implementation"),profile.required("adapter_artifact")))adapter=true;if(!adapter)deny();
 }
 private static void version(JsonNode n){if(!"1.0.0".equals(text(n,"schema_version"))||!"N04".equals(text(n,"node_kind")))bad();}private static PermissionProtocol.Basis basis(JsonNode n){return new PermissionProtocol.Basis(text(n,"version_id"),text(n,"content_sha256"));}private static void artifact(JsonNode n){ProfessionalRuntimeObservations.closed(n,Set.of("artifact_id","sha256","size_bytes","media_type"));WireValues.uuid(text(n,"artifact_id"));WireValues.hash(text(n,"sha256"));size(n);if(text(n,"media_type").isBlank())bad();}private static void size(JsonNode n){if(!text(n,"size_bytes").matches("[1-9][0-9]{0,7}")||Long.parseLong(text(n,"size_bytes"))>67108864)bad();}private static boolean sameTree(JsonNode a,JsonNode b){return FormalTaskNodeAuthority.sameEvidence(a,b);}private static String text(JsonNode n,String f){if(!n.required(f).isTextual())bad();return n.required(f).textValue();}private static void bad(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}private static void deny(){throw new TenantAccessException(ErrorCode.ACCESS_DENIED);}
}
